"use client";

import * as React from "react";

import { validatePincode } from "../../lib/pincode";
import { cn } from "./field";
import { PincodeInput } from "./pincode-input";
import { StateSelect } from "./state-select";

export interface IndianAddress {
  line1: string;
  line2: string;
  landmark: string;
  pincode: string;
  city: string;
  /** Two-letter state code. */
  state: string;
}

export const EMPTY_ADDRESS: IndianAddress = {
  line1: "",
  line2: "",
  landmark: "",
  pincode: "",
  city: "",
  state: "",
};

export interface AddressFormProps {
  value?: IndianAddress;
  defaultValue?: IndianAddress;
  onValueChange?: (address: IndianAddress) => void;
  /**
   * Called when a valid PIN code is entered. Resolve city/state from India
   * Post or your own dataset and return them — the form fills the rest in.
   * Without this, city and state stay manual.
   */
  onPincodeResolve?: (
    pincode: string,
  ) => Promise<{ city?: string; state?: string } | undefined>;
  /** Include a landmark line — expected on most Indian delivery forms. */
  showLandmark?: boolean;
  disabled?: boolean;
  className?: string;
}

const inputClass =
  "h-10 w-full rounded-lg border border-neutral-300 bg-transparent px-3 py-2 text-sm outline-none transition placeholder:text-neutral-400 focus-visible:border-neutral-900 focus-visible:ring-[3px] focus-visible:ring-neutral-900/10 disabled:cursor-not-allowed disabled:opacity-50 dark:border-neutral-700 dark:placeholder:text-neutral-600 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10";

/**
 * A full Indian postal address: two address lines, an optional landmark, then
 * PIN code, city and state.
 *
 * PIN code comes *before* city and state because that's the order that lets a
 * lookup fill the rest in — the opposite of the Western house-number-first
 * convention most form libraries assume.
 */
export function AddressForm({
  value: controlledValue,
  defaultValue = EMPTY_ADDRESS,
  onValueChange,
  onPincodeResolve,
  showLandmark = true,
  disabled,
  className,
}: AddressFormProps) {
  const reactId = React.useId();
  const isControlled = controlledValue !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const address = isControlled ? controlledValue : uncontrolled;

  const [resolving, setResolving] = React.useState(false);

  // The ref keeps `update` stable while still reading the latest address. If
  // `update` closed over `address` directly, a PIN lookup resolving after the
  // user typed elsewhere would spread a stale address and wipe those edits.
  const addressRef = React.useRef(address);
  addressRef.current = address;

  const update = React.useCallback(
    (patch: Partial<IndianAddress>) => {
      const next = { ...addressRef.current, ...patch };
      if (!isControlled) setUncontrolled(next);
      onValueChange?.(next);
    },
    [isControlled, onValueChange],
  );

  // Look up city/state whenever the PIN code becomes valid. The request is
  // guarded so a stale response can't overwrite a newer PIN code's result.
  const requestRef = React.useRef(0);
  React.useEffect(() => {
    if (!onPincodeResolve) return;
    if (!validatePincode(address.pincode).valid) return;

    const requestId = ++requestRef.current;
    setResolving(true);

    onPincodeResolve(address.pincode)
      .then((resolved) => {
        if (requestId !== requestRef.current || !resolved) return;
        update({
          city: resolved.city ?? addressRef.current.city,
          state: resolved.state ?? addressRef.current.state,
        });
      })
      .finally(() => {
        if (requestId === requestRef.current) setResolving(false);
      });
    // Keyed on the PIN code alone — `update` is stable and the rest of the
    // address is read through the ref, so editing other fields won't re-fire it.
  }, [address.pincode, onPincodeResolve, update]);

  return (
    <div className={cn("space-y-3", className)}>
      <div>
        <label
          htmlFor={`${reactId}-line1`}
          className="mb-1.5 block text-sm font-medium"
        >
          Address line 1
        </label>
        <input
          id={`${reactId}-line1`}
          value={address.line1}
          disabled={disabled}
          onChange={(event) => update({ line1: event.target.value })}
          placeholder="Flat / house no., building, apartment"
          autoComplete="address-line1"
          className={inputClass}
        />
      </div>

      <div>
        <label
          htmlFor={`${reactId}-line2`}
          className="mb-1.5 block text-sm font-medium"
        >
          Address line 2
        </label>
        <input
          id={`${reactId}-line2`}
          value={address.line2}
          disabled={disabled}
          onChange={(event) => update({ line2: event.target.value })}
          placeholder="Area, street, sector, village"
          autoComplete="address-line2"
          className={inputClass}
        />
      </div>

      {showLandmark && (
        <div>
          <label
            htmlFor={`${reactId}-landmark`}
            className="mb-1.5 block text-sm font-medium"
          >
            Landmark{" "}
            <span className="font-normal text-neutral-500">(optional)</span>
          </label>
          <input
            id={`${reactId}-landmark`}
            value={address.landmark}
            disabled={disabled}
            onChange={(event) => update({ landmark: event.target.value })}
            placeholder="Near…"
            className={inputClass}
          />
        </div>
      )}

      <div className="grid gap-3 sm:grid-cols-2">
        <PincodeInput
          label="PIN code"
          value={address.pincode}
          disabled={disabled}
          onValueChange={(pincode) => update({ pincode })}
          description={resolving ? "Looking up city and state…" : undefined}
        />

        <div>
          <label
            htmlFor={`${reactId}-city`}
            className="mb-1.5 block text-sm font-medium"
          >
            City / town
          </label>
          <input
            id={`${reactId}-city`}
            value={address.city}
            disabled={disabled}
            onChange={(event) => update({ city: event.target.value })}
            placeholder="City"
            autoComplete="address-level2"
            className={inputClass}
          />
        </div>
      </div>

      <StateSelect
        label="State"
        value={address.state}
        disabled={disabled}
        onValueChange={(state) => update({ state })}
      />
    </div>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

"use client";

import * as React from "react";

import {
  normalizePincode,
  type PincodeResult,
  validatePincode,
} from "../../lib/pincode";
import { cn, controlClasses, Field, FieldBadge, useFieldState } from "./field";

export interface PincodeInputProps
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: PincodeResult) => void;
  validateOn?: "blur" | "change";
  /** Show the derived postal zone. Default `true`. */
  showZone?: boolean;
  /** Reject 9xxxxx (Army Postal Service) — usually right for a home address. */
  rejectArmyPostal?: boolean;
  label?: string;
  description?: string;
  containerClassName?: string;
}

export function PincodeInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  showZone = true,
  rejectArmyPostal = false,
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: PincodeInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `pincode-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<PincodeResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate: validatePincode,
    transform: (raw) => normalizePincode(raw).slice(0, 6),
    validateOn,
  });

  const armyRejected =
    rejectArmyPostal && field.result.valid && field.result.isArmyPostal
      ? "This is an Army Postal Service code — enter a residential PIN code."
      : undefined;

  const zone =
    showZone && field.result.valid && !armyRejected
      ? field.result.zone
      : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={
        field.error ?? armyRejected ?? field.result.covers ?? description
      }
      tone={
        field.error || armyRejected
          ? "error"
          : field.result.covers
            ? "hint"
            : "muted"
      }
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          inputMode="numeric"
          autoComplete="postal-code"
          placeholder={props.placeholder ?? "560001"}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error || armyRejected)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error || armyRejected),
              success: field.success && !armyRejected,
            }),
            "tracking-[0.2em]",
            zone && "pr-32",
            className,
          )}
        />
        {zone && <FieldBadge>{zone}</FieldBadge>}
      </div>
    </Field>
  );
}

"use client";

import { Check, ChevronDown } from "lucide-react";
import * as React from "react";

import {
  INDIAN_STATES,
  type IndianState,
  searchStates,
} from "../../lib/states";
import { cn, controlClasses, Field } from "./field";

export interface StateSelectProps {
  /** Two-letter state code, e.g. `"KA"`. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (code: string, state: IndianState | undefined) => void;
  label?: string;
  description?: string;
  placeholder?: string;
  disabled?: boolean;
  /** Show the numeric GST code alongside each state. */
  showGstCode?: boolean;
  id?: string;
  className?: string;
  containerClassName?: string;
}

/**
 * A searchable state/UT picker following the APG combobox pattern — options are
 * never focusable, focus stays in the input, and `aria-activedescendant` marks
 * the highlighted row.
 */
export function StateSelect({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  label,
  description,
  placeholder = "Select a state…",
  disabled,
  showGstCode = false,
  id,
  className,
  containerClassName,
}: StateSelectProps) {
  const reactId = React.useId();
  const inputId = id ?? `state-${reactId}`;
  const listboxId = `${inputId}-listbox`;
  const messageId = `${inputId}-message`;

  const isControlled = controlledValue !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const code = isControlled ? controlledValue : uncontrolled;
  const selected = INDIAN_STATES.find((s) => s.code === code);

  const [query, setQuery] = React.useState("");
  const [open, setOpen] = React.useState(false);
  const [activeIndex, setActiveIndex] = React.useState(0);

  const containerRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);

  const matches = React.useMemo(() => searchStates(query), [query]);

  // Reset the highlight when the query changes — during render, not in an
  // effect, so no frame paints with a stale highlight.
  const [lastQuery, setLastQuery] = React.useState(query);
  if (lastQuery !== query) {
    setLastQuery(query);
    setActiveIndex(0);
  }

  React.useEffect(() => {
    if (!open) return;
    function onPointerDown(event: PointerEvent) {
      if (!containerRef.current?.contains(event.target as Node)) setOpen(false);
    }
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  function select(state: IndianState) {
    if (!isControlled) setUncontrolled(state.code);
    onValueChange?.(state.code, state);
    setQuery("");
    setOpen(false);
    inputRef.current?.focus();
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (!open) {
      if (event.key === "ArrowDown" || event.key === "Enter") {
        event.preventDefault();
        setOpen(true);
      }
      return;
    }
    switch (event.key) {
      case "ArrowDown":
        event.preventDefault();
        setActiveIndex((i) => (i + 1) % matches.length);
        break;
      case "ArrowUp":
        event.preventDefault();
        setActiveIndex((i) => (i - 1 + matches.length) % matches.length);
        break;
      case "Enter":
        event.preventDefault();
        if (matches[activeIndex]) select(matches[activeIndex]);
        break;
      case "Escape":
        event.preventDefault();
        setOpen(false);
        setQuery("");
        break;
    }
  }

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={description}
      className={containerClassName}
    >
      <div ref={containerRef} className="relative">
        <input
          ref={inputRef}
          id={inputId}
          type="text"
          role="combobox"
          autoComplete="off"
          disabled={disabled}
          placeholder={selected ? selected.name : placeholder}
          value={open ? query : (selected?.name ?? "")}
          onChange={(event) => {
            setQuery(event.target.value);
            setOpen(true);
          }}
          onFocus={() => setOpen(true)}
          onKeyDown={handleKeyDown}
          aria-expanded={open}
          aria-controls={open ? listboxId : undefined}
          aria-autocomplete="list"
          aria-activedescendant={
            open && matches.length > 0
              ? `${listboxId}-option-${activeIndex}`
              : undefined
          }
          aria-describedby={description ? messageId : undefined}
          className={cn(
            controlClasses({ success: Boolean(selected) }),
            "cursor-pointer pr-9 font-sans",
            className,
          )}
        />
        <ChevronDown
          aria-hidden
          className="pointer-events-none absolute right-3 top-1/2 size-4 -translate-y-1/2 text-neutral-500"
        />

        {open && (
          <div
            id={listboxId}
            role="listbox"
            aria-label="Indian states and union territories"
            className="absolute z-50 mt-1.5 max-h-64 w-full overflow-auto rounded-lg border border-neutral-200 bg-white p-1 shadow-xl ring-1 ring-black/5 dark:border-neutral-800 dark:bg-neutral-950 dark:ring-white/10"
          >
            {matches.map((state, index) => (
              // biome-ignore lint/a11y/useFocusableInteractive: APG combobox — focus stays in the input
              // biome-ignore lint/a11y/useKeyWithClickEvents: keys are handled on the input
              <div
                key={state.code}
                id={`${listboxId}-option-${index}`}
                role="option"
                aria-selected={state.code === code}
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => select(state)}
                onMouseEnter={() => setActiveIndex(index)}
                className={cn(
                  "flex cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm",
                  index === activeIndex && "bg-neutral-100 dark:bg-neutral-800",
                )}
              >
                <span className="flex min-w-0 items-center gap-2">
                  {state.code === code ? (
                    <Check className="size-3.5 shrink-0 text-emerald-500" />
                  ) : (
                    <span aria-hidden className="size-3.5 shrink-0" />
                  )}
                  <span className="truncate">{state.name}</span>
                </span>
                <span className="shrink-0 font-mono text-xs text-neutral-500">
                  {showGstCode ? state.gstCode : state.code}
                </span>
              </div>
            ))}
            {matches.length === 0 && (
              <p className="px-2.5 py-6 text-center text-sm text-neutral-500">
                No state matches “{query}”.
              </p>
            )}
          </div>
        )}
      </div>
    </Field>
  );
}

/**
 * States and union territories of India, with the code systems that actually
 * appear in forms: the two-letter ISO/vehicle abbreviation and the numeric GST
 * state code.
 */

export interface IndianState {
  /** Two-letter code — matches vehicle registration and ISO 3166-2:IN. */
  code: string;
  name: string;
  /** Numeric GST state code, as used in the first two digits of a GSTIN. */
  gstCode: string;
  type: "state" | "union territory";
}

export const INDIAN_STATES: readonly IndianState[] = [
  {
    code: "AN",
    name: "Andaman & Nicobar Islands",
    gstCode: "35",
    type: "union territory",
  },
  { code: "AP", name: "Andhra Pradesh", gstCode: "37", type: "state" },
  { code: "AR", name: "Arunachal Pradesh", gstCode: "12", type: "state" },
  { code: "AS", name: "Assam", gstCode: "18", type: "state" },
  { code: "BR", name: "Bihar", gstCode: "10", type: "state" },
  { code: "CH", name: "Chandigarh", gstCode: "04", type: "union territory" },
  { code: "CG", name: "Chhattisgarh", gstCode: "22", type: "state" },
  {
    code: "DN",
